    quickShapeSourcePointsRef.current = [pos.x, pos.y];
    quickShapeStableSourceLengthRef.current = 2;
    // onStageDown(포인터 이벤트 핸들러)에서만 호출되며 아래 타이머도 렌더가 끝난 뒤 시작한다.
    quickShapeStillElapsedRef.current = 0;
