  const selectionOptionsSuppressed =
    advancedFillActive ||
    commentPinArmed ||
    cropRect !== null ||
    dodgeBurnActive ||
    eyedropperActive ||
    liquifyActive ||
    pixelTool !== null ||
    smudgeActive ||
    wetMixActive;
  /**
   * 선택 옵션 줄은 "선택 도구가 켜져 있는 동안" 항상 같은 높이를 차지한다.
   * 예전에는 선택이 생기는 순간에만 44px 스트립이 flow 로 끼어들어 툴 레일·페이지
   * 패널·캔버스·인스펙터가 통째로 아래로 밀렸다(브라우저 실측: 선택할 때마다 캔버스
   * 원점이 95px 이동, 그중 44px 이 이 스트립). Photoshop/CSP 처럼 도구 옵션 줄을
   * 상시 유지해 선택 상태가 캔버스 기하를 건드리지 못하게 한다.
   */
  const selectOptionsStripArmed = tool === "select" && !canvasOnlyMode && !selectionOptionsSuppressed;
  /**
   * ...그리고 그 줄은 "도구와 무관하게" 항상 같은 높이를 차지한다. 도구를 select 로 바꾸는
   * 순간에만 스트립이 flow 에 들어오면, 선택이 아니라 도구 전환이 캔버스 기하를 바꾼다
   * (브라우저 실측: 펜 y=121/h=599 ↔ 선택 y=165/h=555 — 전환 1회마다 원점 44px 이동).
   * 픽셀 도구·크롭·리퀴파이처럼 selectionOptionsSuppressed 를 켜는 무장도 같은 점프를
   * 만들었으므로, 레인 예약은 그 조건들과도 분리한다. 오버레이로 띄우지 않는 이유는 선택
   * 명령 레인과 동일하다 — absolute 로 겹치면 흰 원고 위를 덮는다.
   */
  /**
   * ...단, 그 예약이 값을 하는 곳은 **데스크톱뿐이다.** 360px 모바일에서 이 44px 은 그대로
   * 그리기 면적 손실인데, 정작 레인이 주는 복제·앞뒤·삭제·잠금·대사 편집은 요소를 고르는
   * 순간 뜨는 플로팅 "선택 항목 빠른 작업" 바가 이미 엄지 영역에 제공한다. 그래서 모바일은
   * 레인을 **예약도 렌더도 하지 않는다**(선택 명령 레인도 같은 이유로 함께 빠진다).
   *
   * 조건이 선택 상태가 아니라 뷰포트라는 점이 이 분기의 안전장치다 — 모바일에서는 선택 유무와
   * 무관하게 항상 없으므로 "선택 시 레이아웃 이동 0px" 불변식이 그대로 성립한다.
   */
  const selectionLaneMounted = !isMobile;
  const selectOptionsLaneReserved = !canvasOnlyMode && selectionLaneMounted;

  const studioOptionsBarsSelectionModel = useMemo<StudioOptionsBarsSelectionModel>(() => {
    const count = marqueeIds.length > 0 ? marqueeIds.length : selectedId ? 1 : 0;
    return {
      visible: selectOptionsStripArmed && count > 0 && selectionLaneMounted,
      count,
      label: selected ? elementLabel(selected) : null,
      locked: Boolean(selected?.locked),
      canToggleLock: Boolean(selected),
      textEditLabel:
        selected && !activeSurfaceReviewLocked && !isEffectivelyLocked(selected, groups)
          ? selected.type === "bubble"
            ? "대사 편집"
            : selected.type === "text" || selected.type === "sticker"
              ? "글자 편집"
              : null
          : null,
      canFitBubble:
        selected?.type === "bubble" &&
        !activeSurfaceReviewLocked &&
        !isEffectivelyLocked(selected, groups),
    };
  }, [
    activeSurfaceReviewLocked,
    groups,
    marqueeIds.length,
    selectionLaneMounted,
    selectOptionsStripArmed,
    selected,
    selectedId,
  ]);

  /**
   * 모바일 플로팅 빠른 작업 바의 잠금 버튼이 쓸 상태. 판정식은 `toggleSelectedElementsLocked`
   * 가 다음 잠금 값을 정할 때 쓰는 것과 **같아야** 한다 — 그래야 라벨("잠금"/"잠금 해제")이
   * 실제로 일어날 일을 가리킨다. 그룹에서 상속된 잠금도 잠긴 것으로 본다.
   */
  const mobileSelectionLocked = useMemo(() => {
    const ids = marqueeIds.length > 0 ? marqueeIds : selectedId ? [selectedId] : [];
    if (ids.length === 0) return false;
    const idSet = new Set(ids);
    const picked = elements.filter((element) => idSet.has(element.id));
    return (
      picked.length > 0 &&
      picked.every((element) => isEffectivelyLocked(element, groups))
    );
  }, [elements, groups, marqueeIds, selectedId]);

  // 렌더 시점 ref 스냅샷 — RC 컴파일 자식(캔버스)은 렌더 중 ref 접근이 금지라, 비컴파일
  // 에디터에서 읽어 값으로 전달한다(어차피 렌더 시점 값만 화면에 반영되므로 의미 동일).
  const liveDrawPressureStore = liveDrawPressureStoreRef.current;
  const draftPreviewStore = draftPreviewStoreRef.current;
  const liveInkOverlayRenderer = liveInkOverlayRendererRef.current;
  const liveInkPredictionRenderer = liveInkPredictionRendererRef.current;
  const liveStampOverlayRenderer = liveStampOverlayRendererRef.current;
  const liveDynamicBrushOverlayRenderer = liveDynamicBrushOverlayRendererRef.current;
